  SZGame2D.onKey("Enter", () => {
    mareAlta = false;
  }, "pedido-mare_events_0");
  SZGame2D.onKey("Space", () => {

  }, "pedido-mare_events_1");
  SZGame2D.onKey("ArrowUp", () => {

  }, "pedido-mare_events_2");
